# -*- coding: utf-8 -*-
"""Module contains all exceptions used by Iperf package

:author:
:contact:
"""
from __future__ import absolute_import, division, print_function,\
    unicode_literals
# from ute_core.exception import CoreException

from future import standard_library
standard_library.install_aliases()


class IperfExecutionError(Exception):
    """Exception  is raised if shell command return code is not zero."""


class ProcessIsAlreadyRunning(Exception):
    """Exception is raised if it is try of overwrite process."""


class StartProcessError(Exception):
    """Exception is raised if process is not able to start."""


class StopProcessError(Exception):
    """Exception is raised if process is not able to stop."""


class NoDataReceivedAtIperfServerException(Exception):
    """Exception is raised if no data is received at iperf server"""
    pass


class IperfSummaryNotFound(Exception):
    """Exception raised if Iperf summary line is not found at the end"""
    pass